// Load t-alias.hdf5, exported by `aida-data export t-alias`.
// Generated by aida-data 0.0.0 for HighFive 3.x (H5Easy), tested with HighFive 3.3.0.
// Generated without the file, so it checks the objects that not every dataset has
// with `file.exist`. Get the file with `aida-data export t-alias`, then run
// `aida-data snippet t-alias` again for a version made for it.
//
// Build: h5c++ -std=c++17 -I/path/to/highfive/include load.cpp -o load
// or with CMake:
//   find_package(HighFive REQUIRED)
//   target_link_libraries(load HighFive::HighFive)
// HighFive comes from a package manager (apt install libhighfive-dev,
// conda install highfive, vcpkg install highfive) or a git submodule.
// With HighFive 2.x the CMake target is `HighFive` and DataSet::read_raw(T*)
// is DataSet::read(T*).
#include <highfive/H5Easy.hpp>

#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

int main() {
    H5Easy::File file("t-alias.hdf5", H5Easy::File::ReadOnly);

    // One row per point.
    auto train = H5Easy::load<std::vector<std::vector<float>>>(file, "/train");

    if (file.exist("/test")) {
        // One row per query (MTEB retrieval).
        auto test = H5Easy::load<std::vector<std::vector<float>>>(file, "/test");
        std::cout << "test: " << test.size() << " x " << (test.empty() ? 0 : test[0].size()) << "\n";
    }

    if (file.exist("/colors")) {
        // Integer codes, one column per color.
        auto colors = H5Easy::load<std::vector<std::vector<int64_t>>>(file, "/colors");
        std::cout << "colors: " << colors.size() << " x " << (colors.empty() ? 0 : colors[0].size()) << "\n";
    }

    if (file.exist("/ids")) {
        // One id per row of train.
        auto ids = H5Easy::load<std::vector<std::string>>(file, "/ids");
        std::cout << "ids: " << ids.size() << "\n";
    }

    if (file.exist("/test_ids")) {
        // One id per row of test.
        auto test_ids = H5Easy::load<std::vector<std::string>>(file, "/test_ids");
        std::cout << "test_ids: " << test_ids.size() << "\n";
    }

    if (file.exist("/qrels/query")) {
        // Query id of each relevance judgment.
        auto qrels_query = H5Easy::load<std::vector<std::string>>(file, "/qrels/query");
        std::cout << "qrels/query: " << qrels_query.size() << "\n";
    }

    if (file.exist("/qrels/doc")) {
        // Document id of each relevance judgment.
        auto qrels_doc = H5Easy::load<std::vector<std::string>>(file, "/qrels/doc");
        std::cout << "qrels/doc: " << qrels_doc.size() << "\n";
    }

    if (file.exist("/qrels/score")) {
        // Relevance score of each judgment.
        auto qrels_score = H5Easy::load<std::vector<int64_t>>(file, "/qrels/score");
        std::cout << "qrels/score: " << qrels_score.size() << "\n";
    }

    // Distance of the dataset, e.g. "euclidean" or "cosine".
    auto distance = H5Easy::loadAttribute<std::string>(file, "/", "distance");

    // Number of columns of train.
    auto dimension = H5Easy::loadAttribute<int64_t>(file, "/", "dimension");

    if (file.hasAttribute("color_names")) {
        // Name of each column of colors.
        auto color_names = H5Easy::loadAttribute<std::vector<std::string>>(file, "/", "color_names");
        std::cout << "color_names: " << color_names.size() << "\n";
    }

    if (file.hasAttribute("color_labels")) {
        // JSON text: a list of lists of labels, one list per color.
        // Parsing it needs a JSON library, e.g. nlohmann/json.
        auto color_labels = H5Easy::loadAttribute<std::string>(file, "/", "color_labels");
        std::cout << "color_labels: " << color_labels.size() << "\n";
    }

    // For large data, read into one contiguous row-major buffer instead:
    //   HighFive::DataSet ds = file.getDataSet("/train");
    //   auto dims = ds.getDimensions();
    //   std::vector<float> flat(dims[0] * dims[1]);
    //   ds.read_raw(flat.data());
    // or, with H5_USE_EIGEN defined before including HighFive:
    //   using Matrix = Eigen::Matrix<float, Eigen::Dynamic, Eigen::Dynamic,
    //                                Eigen::RowMajor>;
    //   auto m = H5Easy::load<Matrix>(file, "/train");

    // The shapes of what was loaded.
    std::cout << "train: " << train.size() << " x " << (train.empty() ? 0 : train[0].size()) << "\n";
    std::cout << "distance: " << distance << "\n";
    std::cout << "dimension: " << dimension << "\n";
}
